// Returns the class index; prob gets the share of votes for each class.
static inline int thg_predict(const float *x, float *prob) {
  float p[THG_N_CLASSES] = {0};
  thg_tree_0(x, p);
  thg_tree_1(x, p);
  thg_tree_2(x, p);
  thg_tree_3(x, p);
  thg_tree_4(x, p);
  thg_tree_5(x, p);
  thg_tree_6(x, p);
  thg_tree_7(x, p);
  thg_tree_8(x, p);
  thg_tree_9(x, p);
  int best = 0;
  for (int k = 0; k < THG_N_CLASSES; k++) {
    p[k] /= 10.0f;
    if (p[k] > p[best]) best = k;
    if (prob) prob[k] = p[k];
  }
  return best;
}
